USE maganlal_chikki_bi;
CREATE OR REPLACE VIEW vw_daily_sales AS
SELECT s.sale_date,s.total_sales,s.revenue,COALESCE(i.quantity,0) quantity,COALESCE(i.cogs,0) cogs
FROM (SELECT sale_date,COUNT(*) total_sales,SUM(total) revenue FROM sales WHERE status='completed' GROUP BY sale_date) s
LEFT JOIN (SELECT h.sale_date,SUM(d.quantity) quantity,SUM(d.quantity*d.unit_cost) cogs FROM sales h JOIN sale_items d ON d.sale_id=h.sale_id WHERE h.status='completed' GROUP BY h.sale_date) i ON i.sale_date=s.sale_date;
CREATE OR REPLACE VIEW vw_weekly_sales AS SELECT YEARWEEK(sale_date,3) year_week,SUM(total) revenue,COUNT(*) total_sales FROM sales WHERE status='completed' GROUP BY YEARWEEK(sale_date,3);
CREATE OR REPLACE VIEW vw_monthly_sales AS SELECT DATE_FORMAT(sale_date,'%Y-%m-01') month_start,SUM(total) revenue,COUNT(*) total_sales FROM sales WHERE status='completed' GROUP BY DATE_FORMAT(sale_date,'%Y-%m-01');
CREATE OR REPLACE VIEW vw_product_sales AS SELECT p.product_id,p.product_name,p.category,SUM(si.quantity) quantity,SUM(si.quantity*si.unit_price) revenue,SUM(si.quantity*si.unit_cost) cogs FROM products p JOIN sale_items si ON si.product_id=p.product_id JOIN sales s ON s.sale_id=si.sale_id AND s.status='completed' GROUP BY p.product_id,p.product_name,p.category;
CREATE OR REPLACE VIEW vw_category_sales AS SELECT category,SUM(quantity) quantity,SUM(revenue) revenue FROM vw_product_sales GROUP BY category;
CREATE OR REPLACE VIEW vw_inventory_status AS SELECT p.product_id,p.product_name,p.category,p.current_stock,p.minimum_stock,p.reorder_level,p.current_stock*p.purchase_price stock_value,CASE WHEN p.current_stock<=0 THEN 'Out of stock' WHEN p.current_stock<=p.minimum_stock THEN 'Critical' WHEN p.current_stock<=p.reorder_level THEN 'Low' ELSE 'Healthy' END stock_status FROM products p;
CREATE OR REPLACE VIEW vw_supplier_purchases AS SELECT sp.supplier_id,sp.supplier_name,sp.lead_time_days,(SELECT COUNT(*) FROM purchases p WHERE p.supplier_id=sp.supplier_id) purchases,(SELECT COALESCE(SUM(p.total),0) FROM purchases p WHERE p.supplier_id=sp.supplier_id) purchase_value,(SELECT COALESCE(SUM(pi.quantity),0) FROM purchases p JOIN purchase_items pi ON pi.purchase_id=p.purchase_id WHERE p.supplier_id=sp.supplier_id) purchase_quantity FROM suppliers sp;
CREATE OR REPLACE VIEW vw_financial_summary AS SELECT (SELECT COALESCE(SUM(total),0) FROM sales WHERE status='completed') revenue,(SELECT COALESCE(SUM(si.quantity*si.unit_cost),0) FROM sale_items si JOIN sales s ON s.sale_id=si.sale_id WHERE s.status='completed') cogs,(SELECT COALESCE(SUM(amount),0) FROM expenses) operating_expenses,(SELECT COALESCE(SUM(total),0) FROM sales WHERE status='completed')-(SELECT COALESCE(SUM(si.quantity*si.unit_cost),0) FROM sale_items si JOIN sales s ON s.sale_id=si.sale_id WHERE s.status='completed') gross_profit,(SELECT COALESCE(SUM(total),0) FROM sales WHERE status='completed')-(SELECT COALESCE(SUM(si.quantity*si.unit_cost),0) FROM sale_items si JOIN sales s ON s.sale_id=si.sale_id WHERE s.status='completed')-(SELECT COALESCE(SUM(amount),0) FROM expenses) net_profit;
CREATE OR REPLACE VIEW vw_profit_trend AS SELECT r.sale_date,r.revenue,COALESCE(c.cogs,0) cogs,r.revenue-COALESCE(c.cogs,0) gross_profit FROM (SELECT sale_date,SUM(total) revenue FROM sales WHERE status='completed' GROUP BY sale_date) r LEFT JOIN (SELECT s.sale_date,SUM(si.quantity*si.unit_cost) cogs FROM sales s JOIN sale_items si ON si.sale_id=s.sale_id WHERE s.status='completed' GROUP BY s.sale_date) c ON c.sale_date=r.sale_date;
CREATE OR REPLACE VIEW vw_expense_summary AS SELECT expense_date,category,SUM(amount) amount FROM expenses GROUP BY expense_date,category;
CREATE OR REPLACE VIEW vw_payment_summary AS SELECT payment_date,status,SUM(amount) amount FROM payments GROUP BY payment_date,status;
CREATE OR REPLACE VIEW vw_returns_summary AS SELECT r.return_date,SUM(ri.quantity) return_quantity,SUM(ri.quantity*ri.unit_value) return_value FROM returns r JOIN return_items ri ON ri.return_id=r.return_id GROUP BY r.return_date;
CREATE OR REPLACE VIEW vw_forecast AS SELECT * FROM forecast_results;
CREATE OR REPLACE VIEW vw_reorder_recommendations AS SELECT * FROM reorder_recommendations;
CREATE OR REPLACE VIEW vw_dashboard_summary AS SELECT (SELECT COALESCE(SUM(total),0) FROM sales WHERE status='completed') revenue,(SELECT COUNT(*) FROM sales WHERE status='completed') transactions,(SELECT COUNT(*) FROM vw_inventory_status WHERE stock_status IN ('Low','Critical','Out of stock')) low_stock_items,(SELECT COALESCE(SUM(current_stock*purchase_price),0) FROM products) inventory_value;
